109	package com.posadamareaita;
110	
111	import com.posadamareaita.api.Api;
112	import com.posadamareaita.database.Database;
113	import io.javalin.Javalin;
114	
115	public class Main {
116	    public static void main(String[] args) throws Exception {
117	        // Get environment variables
118	        String dbUrl = System.getenv("DB_URL");
119	        String dbUser = System.getenv("DB_USER");
120	        String dbPassword = System.getenv("DB_PASSWORD");
121	        String portStr = System.getenv("PORT");
122	        int port = portStr != null ? Integer.parseInt(portStr) : 7070;
123	
124	        // Initialize database
125	        if (dbUrl == null || dbUser == null || dbPassword == null) {
126	            throw new IllegalArgumentException("Missing database configuration");
127	        }
128	
129	        Database.initialize(dbUrl, dbUser, dbPassword);
130	
131	        // Start server
132	        Javalin app = Javalin.create()
133	                .start(port);
134	
135	        // Setup routes
136	        Api.setupRoutes(app);
137	
138	        System.out.println("Server started on port " + port);
139	    }
140	}
141	package com.posadamareaita.api;
142	
143	import com.google.gson.Gson;
144	import com.google.gson.JsonObject;
145	import com.posadamareaita.domain.Reservation;
146	import com.posadamareaita.domain.Room;
147	import com.posadamareaita.repository.MessageRepository;
148	import com.posadamareaita.repository.ReservationRepository;
149	import com.posadamareaita.repository.RoomRepository;
150	import com.posadamareaita.service.DocumentService;
151	import com.posadamareaita.service.ReportService;
152	import com.posadamareaita.service.ReservationService;
153	import io.javalin.Javalin;
154	import io.javalin.http.Context;
155	import java.math.BigDecimal;
156	import java.time.LocalDate;
157	import java.time.YearMonth;
158	import java.time.format.DateTimeFormatter;
159	import java.util.HashMap;
160	import java.util.List;
161	import java.util.Map;
162	import java.util.Optional;
163	
164	public class Api {
165	    private static final Gson gson = new Gson();
166	    private static final DateTimeFormatter dateFormatter = DateTimeFormatter.ISO_LOCAL_DATE;
167	
168	    public static void setupRoutes(Javalin app) {
169	        app.get("/rooms", Api::getRooms);
170	        app.post("/reservations", Api::createReservation);
171	        app.get("/reservations/{id}", Api::getReservation);
172	        app.post("/reservations/{id}/confirmation", Api::confirmReservation);
173	        app.post("/reservations/{id}/cancellation", Api::cancelReservation);
174	        app.post("/reservations/{id}/check-in", Api::checkInReservation);
175	        app.post("/reservations/{id}/check-out", Api::checkOutReservation);
176	        app.get("/reservations/{id}/document", Api::getDocument);
177	        app.get("/messages", Api::getMessages);
178	        app.get("/reports/occupancy", Api::getOccupancyReport);
179	        app.get("/reports/revenue", Api::getRevenueReport);
180	    }
181	
182	    private static void getRooms(Context ctx) throws Exception {
183	        List<Room> rooms = RoomRepository.findAll();
184	        ctx.json(rooms.stream().map(r -> new HashMap<String, Object>() {{
185	            put("number", r.getNumber());
186	            put("type", r.getType().getDisplayName());
187	            put("capacity", r.getCapacity());
188	            put("nightlyRate", r.getNightlyRate());
189	        }}).toList());
190	    }
191	
192	    private static void createReservation(Context ctx) throws Exception {
193	        try {
194	            JsonObject body = gson.fromJson(ctx.body(), JsonObject.class);
195	
196	            // Validate required fields
197	            if (!body.has("roomNumber") || !body.has("guestName") || !body.has("guestEmail") ||
198	                !body.has("checkIn") || !body.has("checkOut") || !body.has("guests") || !body.has("ratePlan")) {
199	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Missing required fields"));
200	                return;
201	            }
202	
203	            int roomNumber = body.get("roomNumber").getAsInt();
204	            String guestName = body.get("guestName").getAsString();
205	            String guestEmail = body.get("guestEmail").getAsString();
206	
207	            LocalDate checkIn = LocalDate.parse(body.get("checkIn").getAsString(), dateFormatter);
208	            LocalDate checkOut = LocalDate.parse(body.get("checkOut").getAsString(), dateFormatter);
209	
210	            int guests = body.get("guests").getAsInt();
211	            String ratePlanStr = body.get("ratePlan").getAsString();
212	
213	            // Validate rate plan
214	            try {
215	                com.posadamareaita.domain.RatePlan.valueOf(ratePlanStr);
216	            } catch (IllegalArgumentException e) {
217	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid rate plan"));
218	                return;
219	            }
220	
221	            // Get identification fields
222	            String guestCpf = body.has("guestCpf") && !body.get("guestCpf").isJsonNull() ? body.get("guestCpf").getAsString() : null;
223	            String companyCnpj = body.has("companyCnpj") && !body.get("companyCnpj").isJsonNull() ? body.get("companyCnpj").getAsString() : null;
224	            String companyName = body.has("companyName") && !body.get("companyName").isJsonNull() ? body.get("companyName").getAsString() : null;
225	            String guestPassport = body.has("guestPassport") && !body.get("guestPassport").isJsonNull() ? body.get("guestPassport").getAsString() : null;
226	            String guestCountry = body.has("guestCountry") && !body.get("guestCountry").isJsonNull() ? body.get("guestCountry").getAsString() : null;
227	
228	            Optional<Reservation> result = ReservationService.createReservation(
229	                    roomNumber, guestName, guestEmail, checkIn, checkOut, guests, ratePlanStr,
230	                    guestCpf, companyCnpj, companyName, guestPassport, guestCountry
231	            );
232	
233	            if (result.isEmpty()) {
234	                // Check what went wrong
235	                Optional<Room> room = RoomRepository.findByNumber(roomNumber);
236	                if (room.isEmpty()) {
237	                    ctx.status(404).json(new ErrorResponse("ROOM_NOT_FOUND", "Room not found"));
238	                } else if (guests > room.get().getCapacity()) {
239	                    ctx.status(422).json(new ErrorResponse("CAPACITY_EXCEEDED", "Too many guests for this room"));
240	                } else if (guests < 1 || !checkOut.isAfter(checkIn)) {
241	                    ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid request data"));
242	                } else {
243	                    ctx.status(409).json(new ErrorResponse("ROOM_UNAVAILABLE", "Room is not available for these dates"));
244	                }
245	                return;
246	            }
247	
248	            ctx.status(201).json(buildReservationResponse(result.get()));
249	        } catch (Exception e) {
250	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid request"));
251	        }
252	    }
253	
254	    private static void getReservation(Context ctx) throws Exception {
255	        try {
256	            long id = Long.parseLong(ctx.pathParam("id"));
257	            Optional<Reservation> res = ReservationRepository.findById(id);
258	
259	            if (res.isEmpty()) {
260	                ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
261	                return;
262	            }
263	
264	            ctx.json(buildReservationResponse(res.get()));
265	        } catch (Exception e) {
266	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
267	        }
268	    }
269	
270	    private static void confirmReservation(Context ctx) throws Exception {
271	        try {
272	            long id = Long.parseLong(ctx.pathParam("id"));
273	            JsonObject body = gson.fromJson(ctx.body(), JsonObject.class);
274	
275	            if (!body.has("amountPaid")) {
276	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Missing amountPaid"));
277	                return;
278	            }
279	
280	            BigDecimal amountPaid = body.get("amountPaid").getAsBigDecimal();
281	            Optional<Reservation> result = ReservationService.confirm(id, amountPaid);
282	
283	            if (result.isEmpty()) {
284	                Optional<Reservation> res = ReservationRepository.findById(id);
285	                if (res.isEmpty()) {
286	                    ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
287	                } else {
288	                    ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", "Cannot confirm this reservation"));
289	                }
290	                return;
291	            }
292	
293	            ctx.json(buildReservationResponse(result.get()));
294	        } catch (Exception e) {
295	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid request"));
296	        }
297	    }
298	
299	    private static void cancelReservation(Context ctx) throws Exception {
300	        try {
301	            long id = Long.parseLong(ctx.pathParam("id"));
302	            Optional<Reservation> result = ReservationService.cancel(id);
303	
304	            if (result.isEmpty()) {
305	                Optional<Reservation> res = ReservationRepository.findById(id);
306	                if (res.isEmpty()) {
307	                    ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
308	                } else {
309	                    ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", "Cannot cancel this reservation"));
310	                }
311	                return;
312	            }
313	
314	            ctx.json(buildReservationResponse(result.get()));
315	        } catch (Exception e) {
316	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
317	        }
318	    }
319	
320	    private static void checkInReservation(Context ctx) throws Exception {
321	        try {
322	            long id = Long.parseLong(ctx.pathParam("id"));
323	            Optional<Reservation> result = ReservationService.checkIn(id);
324	
325	            if (result.isEmpty()) {
326	                Optional<Reservation> res = ReservationRepository.findById(id);
327	                if (res.isEmpty()) {
328	                    ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
329	                } else {
330	                    ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", "Cannot check in this reservation"));
331	                }
332	                return;
333	            }
334	
335	            ctx.json(buildReservationResponse(result.get()));
336	        } catch (Exception e) {
337	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
338	        }
339	    }
340	
341	    private static void checkOutReservation(Context ctx) throws Exception {
342	        try {
343	            long id = Long.parseLong(ctx.pathParam("id"));
344	            Optional<Reservation> result = ReservationService.checkOut(id);
345	
346	            if (result.isEmpty()) {
347	                Optional<Reservation> res = ReservationRepository.findById(id);
348	                if (res.isEmpty()) {
349	                    ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
350	                } else {
351	                    ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", "Cannot check out this reservation"));
352	                }
353	                return;
354	            }
355	
356	            ctx.json(buildReservationResponse(result.get()));
357	        } catch (Exception e) {
358	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
359	        }
360	    }
361	
362	    private static void getDocument(Context ctx) throws Exception {
363	        try {
364	            long id = Long.parseLong(ctx.pathParam("id"));
365	            Optional<Reservation> opt = ReservationService.getDocument(id);
366	
367	            if (opt.isEmpty()) {
368	                ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
369	                return;
370	            }
371	
372	            Reservation res = opt.get();
373	            Optional<Room> room = RoomRepository.findByNumber(res.getRoomNumber());
374	            if (room.isEmpty()) {
375	                ctx.status(404).json(new ErrorResponse("ROOM_NOT_FOUND", "Room not found"));
376	                return;
377	            }
378	
379	            ctx.json(DocumentService.generateDocumentResponse(res, room.get()));
380	        } catch (Exception e) {
381	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
382	        }
383	    }
384	
385	    private static void getMessages(Context ctx) throws Exception {
386	        List<com.posadamareaita.domain.Message> messages = MessageRepository.findAll();
387	        ctx.json(messages.stream().map(m -> new HashMap<String, Object>() {{
388	            put("id", m.getId());
389	            put("channel", m.getChannel());
390	            put("to", m.getTo());
391	            put("subject", m.getSubject());
392	            put("body", m.getBody());
393	        }}).toList());
394	    }
395	
396	    private static void getOccupancyReport(Context ctx) throws Exception {
397	        try {
398	            String dateStr = ctx.queryParam("date");
399	            if (dateStr == null) {
400	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Missing date parameter"));
401	                return;
402	            }
403	
404	            LocalDate date = LocalDate.parse(dateStr, dateFormatter);
405	            String report = ReportService.generateOccupancyReport(date);
406	            ctx.contentType("text/csv; charset=utf-8").result(report);
407	        } catch (Exception e) {
408	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid date format"));
409	        }
410	    }
411	
412	    private static void getRevenueReport(Context ctx) throws Exception {
413	        try {
414	            String monthStr = ctx.queryParam("month");
415	            if (monthStr == null) {
416	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Missing month parameter"));
417	                return;
418	            }
419	
420	            YearMonth ym = YearMonth.parse(monthStr);
421	            String report = ReportService.generateRevenueReport(ym.getYear(), ym.getMonthValue());
422	            ctx.contentType("text/csv; charset=utf-8").result(report);
423	        } catch (Exception e) {
424	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid month format"));
425	        }
426	    }
427	
428	    private static Map<String, Object> buildReservationResponse(Reservation res) {
429	        Map<String, Object> response = new HashMap<>();
430	        response.put("id", res.getId());
431	        response.put("roomNumber", res.getRoomNumber());
432	        response.put("guestName", res.getGuestName());
433	        response.put("guestEmail", res.getGuestEmail());
434	        response.put("checkIn", res.getCheckIn().toString());
435	        response.put("checkOut", res.getCheckOut().toString());
436	        response.put("guests", res.getGuests());
437	        response.put("ratePlan", res.getRatePlan().toString());
438	        response.put("nights", res.getNights());
439	        response.put("subtotal", res.getSubtotal());
440	        response.put("discount", res.getDiscount());
441	        response.put("total", res.getTotal());
442	        response.put("status", res.getStatus().toString());
443	        response.put("amountPaid", res.getAmountPaid());
444	        response.put("refund", res.getRefund());
445	        response.put("guestCpf", res.getGuestCpf());
446	        response.put("companyCnpj", res.getCompanyCnpj());
447	        response.put("companyName", res.getCompanyName());
448	        response.put("guestPassport", res.getGuestPassport());
449	        response.put("guestCountry", res.getGuestCountry());
450	        return response;
451	    }
452	}
