192	    private static void createReservation(Context ctx) throws Exception {
193	        try {
194	            JsonObject body = gson.fromJson(ctx.body(), JsonObject.class);
195	
196	            // Validate required fields
197	            if (!body.has("roomNumber") || !body.has("guestName") || !body.has("guestEmail") ||
198	                !body.has("checkIn") || !body.has("checkOut") || !body.has("guests") || !body.has("ratePlan")) {
199	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Missing required fields"));
200	                return;
201	            }
202	
203	            int roomNumber = body.get("roomNumber").getAsInt();
204	            String guestName = body.get("guestName").getAsString();
205	            String guestEmail = body.get("guestEmail").getAsString();
206	
207	            LocalDate checkIn = LocalDate.parse(body.get("checkIn").getAsString(), dateFormatter);
208	            LocalDate checkOut = LocalDate.parse(body.get("checkOut").getAsString(), dateFormatter);
209	
210	            int guests = body.get("guests").getAsInt();
211	            String ratePlanStr = body.get("ratePlan").getAsString();
212	
213	            // Validate rate plan
214	            try {
215	                com.posadamareaita.domain.RatePlan.valueOf(ratePlanStr);
216	            } catch (IllegalArgumentException e) {
217	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid rate plan"));
218	                return;
219	            }
220	
221	            // Get identification fields
222	            String guestCpf = body.has("guestCpf") && !body.get("guestCpf").isJsonNull() ? body.get("guestCpf").getAsString() : null;
223	            String companyCnpj = body.has("companyCnpj") && !body.get("companyCnpj").isJsonNull() ? body.get("companyCnpj").getAsString() : null;
224	            String companyName = body.has("companyName") && !body.get("companyName").isJsonNull() ? body.get("companyName").getAsString() : null;
225	            String guestPassport = body.has("guestPassport") && !body.get("guestPassport").isJsonNull() ? body.get("guestPassport").getAsString() : null;
226	            String guestCountry = body.has("guestCountry") && !body.get("guestCountry").isJsonNull() ? body.get("guestCountry").getAsString() : null;
227	
228	            Optional<Reservation> result = ReservationService.createReservation(
229	                    roomNumber, guestName, guestEmail, checkIn, checkOut, guests, ratePlanStr,
230	                    guestCpf, companyCnpj, companyName, guestPassport, guestCountry
231	            );
232	
233	            if (result.isEmpty()) {
234	                // Check what went wrong
235	                Optional<Room> room = RoomRepository.findByNumber(roomNumber);
236	                if (room.isEmpty()) {
237	                    ctx.status(404).json(new ErrorResponse("ROOM_NOT_FOUND", "Room not found"));
238	                } else if (guests > room.get().getCapacity()) {
239	                    ctx.status(422).json(new ErrorResponse("CAPACITY_EXCEEDED", "Too many guests for this room"));
240	                } else if (guests < 1 || !checkOut.isAfter(checkIn)) {
241	                    ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid request data"));
242	                } else {
243	                    ctx.status(409).json(new ErrorResponse("ROOM_UNAVAILABLE", "Room is not available for these dates"));
244	                }
245	                return;
246	            }
247	
248	            ctx.status(201).json(buildReservationResponse(result.get()));
249	        } catch (Exception e) {
250	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid request"));
251	        }
252	    }
