143	public class ReportService {
144	    public static String generateOccupancyReport(LocalDate date) throws Exception {
145	        List<Reservation> reservations = ReservationRepository.findByDateAndStatus(date);
146	        List<Room> rooms = RoomRepository.findAll();
147	
148	        StringBuilder csv = new StringBuilder();
149	        csv.append("room,type,reservation,check_in,check_out\n");
150	
151	        int occupiedCount = 0;
152	        for (Reservation res : reservations) {
153	            Room room = rooms.stream().filter(r -> r.getNumber() == res.getRoomNumber()).findFirst().orElse(null);
154	            if (room != null) {
155	                csv.append(room.getNumber()).append(",");
156	                csv.append(room.getType().getDisplayName()).append(",");
157	                csv.append(res.getId()).append(",");
158	                csv.append(FormattingUtil.formatDateISO(res.getCheckIn())).append(",");
159	                csv.append(FormattingUtil.formatDateISO(res.getCheckOut())).append("\n");
160	                occupiedCount++;
161	            }
162	        }
163	
164	        csv.append("total,").append(occupiedCount).append("/").append(rooms.size()).append("\n");
165	
166	        return csv.toString();
167	    }
168	
169	    public static String generateRevenueReport(int year, int month) throws Exception {
170	        List<Reservation> reservations = ReservationRepository.findByMonthAndStatus(year, month);
171	
172	        StringBuilder csv = new StringBuilder();
173	        csv.append("reservation,room,check_in,check_out,status,amount\n");
174	
175	        BigDecimal total = BigDecimal.ZERO;
176	        for (Reservation res : reservations) {
177	            BigDecimal amount = res.getAmountPaid();
178	            if (res.getRefund() != null) {
179	                amount = amount.subtract(res.getRefund());
180	            }
181	
182	            csv.append(res.getId()).append(",");
183	            csv.append(res.getRoomNumber()).append(",");
184	            csv.append(FormattingUtil.formatDateISO(res.getCheckIn())).append(",");
185	            csv.append(FormattingUtil.formatDateISO(res.getCheckOut())).append(",");
186	            csv.append(res.getStatus().toString()).append(",");
187	            csv.append(String.format("%.2f", amount)).append("\n");
188	
189	            total = total.add(amount);
190	        }
191	
192	        csv.append("total,,,,").append(String.format("%.2f", total)).append("\n");
193	
194	        return csv.toString();
195	    }
196	}
