212	public class ReservationService {
213	    public static Optional<Reservation> createReservation(int roomNumber, String guestName, String guestEmail,
214	                                                          LocalDate checkIn, LocalDate checkOut, int guests,
215	                                                          String ratePlanStr, String guestCpf, String companyCnpj,
216	                                                          String companyName, String guestPassport, String guestCountry)
217	            throws Exception {
218	
219	        // Validate identification
220	        int identificationCount = (guestCpf != null ? 1 : 0) +
221	                                  (companyCnpj != null ? 1 : 0) +
222	                                  (guestPassport != null ? 1 : 0);
223	        if (identificationCount != 1) {
224	            return Optional.empty();
225	        }
226	
227	        // Validate guests
228	        if (guests < 1) {
229	            return Optional.empty();
230	        }
231	
232	        // Validate dates
233	        if (!checkOut.isAfter(checkIn)) {
234	            return Optional.empty();
235	        }
236	
237	        // Get room
238	        Optional<Room> room = RoomRepository.findByNumber(roomNumber);
239	        if (room.isEmpty()) {
240	            return Optional.empty();
241	        }
242	
243	        // Check capacity
244	        if (guests > room.get().getCapacity()) {
245	            return Optional.empty();
246	        }
247	
248	        // Check availability
249	        List<Reservation> conflicts = ReservationRepository.findByRoomAndDateRange(roomNumber, checkIn, checkOut);
250	        if (!conflicts.isEmpty()) {
251	            return Optional.empty();
252	        }
253	
254	        // Calculate price
255	        RatePlan ratePlan = RatePlan.valueOf(ratePlanStr);
256	        PriceCalculator.PriceResult priceResult = PriceCalculator.calculatePrice(room.get(), checkIn, checkOut, ratePlan);
257	
258	        // Create reservation
259	        Reservation res = new Reservation(roomNumber, guestName, guestEmail, checkIn, checkOut, guests, ratePlan,
260	                guestCpf, companyCnpj, companyName, guestPassport, guestCountry);
261	        res.setNights((int) java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut));
262	        res.setSubtotal(priceResult.subtotal);
263	        res.setDiscount(priceResult.discount);
264	        res.setTotal(priceResult.total);
265	
266	        long id = ReservationRepository.create(res);
267	        res.setId(id);
268	
269	        return Optional.of(res);
270	    }
271	
272	    public static Optional<Reservation> confirm(long reservationId, BigDecimal amountPaid) throws Exception {
273	        Optional<Reservation> opt = ReservationRepository.findById(reservationId);
274	        if (opt.isEmpty()) {
275	            return Optional.empty();
276	        }
277	
278	        Reservation res = opt.get();
279	        if (res.getStatus() != ReservationStatus.PENDING) {
280	            return Optional.empty();
281	        }
282	
283	        res.setStatus(ReservationStatus.CONFIRMED);
284	        res.setAmountPaid(amountPaid);
285	        ReservationRepository.update(res);
286	
287	        // Send confirmation email
288	        Optional<Room> room = RoomRepository.findByNumber(res.getRoomNumber());
289	        if (room.isPresent()) {
290	            String documentText;
291	            if (res.getGuestCpf() != null) {
292	                documentText = DocumentService.generateReceiptPT(res, room.get());
293	            } else if (res.getCompanyCnpj() != null) {
294	                documentText = DocumentService.generateInvoice(res, room.get());
295	            } else {
296	                documentText = DocumentService.generateBookingReceipt(res, room.get());
297	            }
298	
299	            String emailBody = buildConfirmationEmail(res, documentText);
300	            MessageService.sendEmail(res.getGuestEmail(), "Reserva confirmada - Pousada Maré Alta", emailBody);
301	        }
302	
303	        return Optional.of(res);
304	    }
