340	    public static Optional<Reservation> cancel(long reservationId) throws Exception {
341	        Optional<Reservation> opt = ReservationRepository.findById(reservationId);
342	        if (opt.isEmpty()) {
343	            return Optional.empty();
344	        }
345	
346	        Reservation res = opt.get();
347	        if (res.getStatus() == ReservationStatus.CHECKED_IN ||
348	            res.getStatus() == ReservationStatus.CHECKED_OUT ||
349	            res.getStatus() == ReservationStatus.CANCELLED) {
350	            return Optional.empty();
351	        }
352	
353	        // Calculate refund before changing status
354	        ReservationStatus originalStatus = res.getStatus();
355	        if (originalStatus == ReservationStatus.CONFIRMED) {
356	            if (res.getRatePlan() == RatePlan.STANDARD) {
357	                res.setRefund(res.getAmountPaid());
358	            } else {
359	                res.setRefund(BigDecimal.ZERO);
360	            }
361	        } else {
362	            res.setRefund(BigDecimal.ZERO);
363	        }
364	
365	        res.setStatus(ReservationStatus.CANCELLED);
366	
367	        ReservationRepository.update(res);
368	
369	        return Optional.of(res);
370	    }
