353	    public static Optional<Room> findByNumber(int number) throws SQLException {
354	        try (Connection conn = Database.getDataSource().getConnection();
355	             PreparedStatement stmt = conn.prepareStatement("SELECT * FROM rooms WHERE number = ?")) {
356	            stmt.setInt(1, number);
357	            var resultSet = stmt.executeQuery();
358	            if (resultSet.next()) {
359	                return Optional.of(mapRoom(resultSet));
360	            }
361	            return Optional.empty();
362	        }
